static uintptr_t som_string_write_shown_f64(struct som_string* self, uintptr_t at, double* value, uintptr_t len) {
    uint8_t* data = som_string_data(self);
    som_f64_display(value, (uint8_t*)(data + at));
    return at + len;
}

int main(int argc, char** argv) {
    som_argc = argc;
    som_argv = argv;
    som_main();
    return 0;
}
